export const ngEntryFor=number=>{
 if(number>=49&&number<=56||number===64||number===65)return 'hedge';
 if(number>=66&&number<=90)return 'pond';
 if(number>=108&&number<=112)return 'picnic';
 if(number>=133&&number<=137)return 'blackAnt';
 if(number===152||number===153)return 'woodpile';
 if(number===184||number===185)return 'bottle';
 if(number===198||number===199)return 'castle';
 if(number===210||number===211)return 'stump';
 if(number>=212&&number<=215)return 'undershed';
 if(number>=216)return 'bin';
 return '';
};
